package dev.raf.radar;
import android.content.*;import android.os.SystemClock;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import org.json.*;
final class Statistics {
 static final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();static Context app;static ObservationQueue queue;static long retryAt;static int failures;
 interface Transport{JSONObject send(JSONObject body,String token)throws Exception;}static Transport transport=Statistics::request;
 static synchronized void init(Context c){if(app!=null)return;app=c.getApplicationContext();queue=new ObservationQueue(new File(app.getFilesDir(),"statistics/observations.json"),System::currentTimeMillis);worker.scheduleWithFixedDelay(()->{try{flush();}catch(Exception e){Diagnostics.once("statistics","queue_failed",true);}},30,60,TimeUnit.SECONDS);}
 static void capture(Context c,Point p,List<Store.Reading> readings){init(c);int owner=new Store(c).prefs.getInt("accountId",0);worker.execute(()->{if(queue.capture(owner,p,readings,BuildConfig.VERSION_NAME,TimeZone.getDefault().getID()))Diagnostics.info("statistics","sample_saved");});}
 static void flush()throws Exception{if(app==null||SystemClock.elapsedRealtime()<retryAt)return;Store store=new Store(app);int owner=store.prefs.getInt("accountId",0);if(owner<1)return;String token=AccountClient.session(store);if(token==null)return;JSONArray rows=queue.batch(owner);if(rows.length()==0)return;try{JSONObject response=transport.send(new JSONObject().put("observations",rows),token);JSONArray accepted=response.getJSONArray("accepted");queue.acknowledge(accepted);failures=0;retryAt=SystemClock.elapsedRealtime()+15000;store.prefs.edit().putLong("statisticsUploadedAt",System.currentTimeMillis()).apply();Diagnostics.info("statistics","uploaded");}catch(Exception e){failures=Math.min(6,failures+1);retryAt=SystemClock.elapsedRealtime()+Math.min(3600000,30000L*(1L<<failures));Diagnostics.error("statistics","upload_failed",e,0,-1,-1,null);}}
 static JSONObject request(JSONObject body,String token)throws Exception{long started=SystemClock.elapsedRealtime();HttpURLConnection c=(HttpURLConnection)new URL("https://radar-presence.vercel.app/api/statistics").openConnection();c.setConnectTimeout(8000);c.setReadTimeout(30000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Authorization","Bearer "+token);try{try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}int status=c.getResponseCode();Diagnostics.record("statistics","http_response",status==200?"info":"error",null,status,SystemClock.elapsedRealtime()-started,-1,null);if(status!=200){Diagnostics.error("statistics","http_error",null,status,-1,-1,null);throw new IOException("statistics_http_"+status);}try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>32000)throw new IOException("statistics_response_size");out.write(buffer,0,n);}return new JSONObject(out.toString("UTF-8"));}}catch(Exception e){Diagnostics.detail("statistics","transport_failed","kind",Diagnostics.cause(e),"rttMs",SystemClock.elapsedRealtime()-started);throw e;}finally{c.disconnect();}}
}

